glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
out vec4 v_thisPos;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
uniform PointData {
  vec2 firstPos;
  vec2 secondPos;
  float mode;
  float p;
};
vec2 getSymmetricPos(vec2 sp,vec2 pos1, vec2 pos2)
{
  float disX = pos2.x - pos1.x;
  float disY = pos2.y - pos1.y;
  float k1 = disY/disX;
  float y = (sp.y*k1*k1  + sp.x*k1 + k1*sp.x - k1*pos1.x*2.0 + pos1.y*2.0 - sp.y)/(1.0+k1*k1);
  float x = (y - sp.y)/(-1.0/k1)+sp.x;
  return vec2(x,y);
}
void main () {
  vec4 pos = vec4(a_position,1.0);
  v_thisPos = vec4(pos);
  if(mode > 0.0){
    float pp = 0.5 + 0.5 * p;
    vec2 pos1 = vec2(firstPos.x + (secondPos.x - firstPos.x)*0.5 , firstPos.y + (secondPos.y - firstPos.y)*0.5);
    vec2 pos3 = vec2(firstPos.x + (secondPos.x - firstPos.x)*pp , firstPos.y + (secondPos.y - firstPos.y)*pp);
    vec2 sp = vec2( pos.x , pos.y );
    float k = ( secondPos.y - firstPos.y)/(secondPos.x - firstPos.x);
    k = -1.0/k;
    float b = pos1.y -  k*pos1.x;
    vec2 pos2 = vec2(0,b);
    vec2 symmetricPos1 = getSymmetricPos(sp,pos1,pos2);
    float b2 = pos3.y -  k*pos3.x;
    vec2 pos4 = vec2(0,b2);
    vec2 symmetricPos2 = getSymmetricPos(sp,pos3,pos4);
    pos.x = pos.x + symmetricPos1.x - symmetricPos2.x;
    pos.y = pos.y + symmetricPos1.y - symmetricPos2.y;
  }
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos ;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
in vec4 v_thisPos;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform PointData {
  vec2 firstPos;
  vec2 secondPos;
  float mode;
  float p;
};
bool isHide(){
  float pp = 0.5;
  if(mode > 0.0){
    pp = pp + 0.5 * p;
  }
  if (secondPos.y == firstPos.y){
    float xw = (secondPos.x - firstPos.x)*pp;
    if (  xw > 0.0  && v_thisPos.x < xw + firstPos.x){
      return true;
    }else if (xw < 0.0  && v_thisPos.x > xw + firstPos.x){
      return true;
    }
  }
  float k = ( secondPos.y - firstPos.y)/(secondPos.x - firstPos.x);
  k = -1.0/k;
  float b = (firstPos.y + (secondPos.y - firstPos.y)*pp) -  k* (firstPos.x +(secondPos.x - firstPos.x)*pp);
  float y = k*v_thisPos.x + b;
  if (secondPos.y  < firstPos.y && v_thisPos.y > y){
      return true;
  }else if (secondPos.y > firstPos.y && v_thisPos.y < y){
      return true;
  }
  return false;
}
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  o *= v_color;
  ALPHA_TEST(o);
  if (isHide()){
    o.a = 0.0;
  }
  gl_FragColor = o;
}

